const retentionCandidates = `-- name: RetentionCandidates :many
SELECT id, project_id, kind, object_key, size_bytes, checksum, started_at, finished_at, status, expires_at, storage_target_id, operation_id, key_wrapped, error, deleted_at FROM backups
WHERE kind = $1 AND status = 'succeeded'
  AND (($2::uuid IS NULL AND project_id IS NULL) OR project_id = $2)
ORDER BY finished_at DESC
`

type RetentionCandidatesParams struct {
	Kind      string
	ProjectID *uuid.UUID
}

// RetentionCandidates lists the succeeded backups of one kind for a project
// (or metadata backups when project_id is null), newest first.
func (q *Queries) RetentionCandidates(ctx context.Context, arg RetentionCandidatesParams) ([]Backup, error) {
	rows, err := q.db.Query(ctx, retentionCandidates, arg.Kind, arg.ProjectID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Backup
	for rows.Next() {
		var i Backup
		if err := rows.Scan(
			&i.ID,
			&i.ProjectID,
			&i.Kind,
			&i.ObjectKey,
			&i.SizeBytes,
			&i.Checksum,
			&i.StartedAt,
			&i.FinishedAt,
			&i.Status,
			&i.ExpiresAt,
			&i.StorageTargetID,
			&i.OperationID,
			&i.KeyWrapped,
			&i.Error,
			&i.DeletedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

